window.VO = [{"id":"o01","text":"You are under digital arrest.","at":0.24,"t0":0.12,"t1":1.938},{"id":"o02","text":"Do not hang up.","at":4.476,"t0":2.238,"t1":3.693},{"id":"n01","text":"You know this is a scam.","at":7.986,"t0":3.993,"t1":6.175},{"id":"n02","text":"Would you fall for it?","at":12.95,"t0":6.475,"t1":8.293},{"id":"n03","text":"He's made three mistakes. Find them.","at":17.186,"t0":8.593,"t1":10.775},{"id":"o03","text":"A parcel in your name.","at":22.15,"t0":11.075,"t1":12.893},{"id":"o04","text":"Five fake passports.","at":26.386,"t0":13.193,"t1":14.284},{"id":"o05","text":"Your pension is frozen.","at":29.168,"t0":14.584,"t1":16.039},{"id":"o06","text":"Show me your gold.","at":32.676,"t0":16.338,"t1":17.793},{"id":"o07","text":"Stay in your room, madam.","at":36.186,"t0":18.093,"t1":19.911},{"id":"o08","text":"Tell no one.","at":40.422,"t0":20.211,"t1":21.302},{"id":"o09","text":"That is my team.","at":43.204,"t0":21.602,"t1":23.057},{"id":"n04","text":"You just looked at your door, didn't you?","at":46.712,"t0":23.356,"t1":26.265},{"id":"n05","text":"Even though his badge says poilce, there's a pressure cooker in his police station, and there's no such thing as a digital arrest.","at":53.13,"t0":26.565,"t1":34.929},{"id":"n06","text":"You only know that because somebody told you.","at":70.458,"t0":35.229,"t1":38.138},{"id":"n07","text":"Nobody told her.","at":76.876,"t0":38.438,"t1":39.529},{"id":"n08","text":"This was never your call.","at":79.658,"t0":39.829,"t1":41.647},{"id":"n09","text":"While you hunted for mistakes, she took off her bangles.","at":83.894,"t0":41.947,"t1":45.583},{"id":"n10","text":"She corrected exam papers for thirty years.","at":91.768,"t0":45.884,"t1":48.429},{"id":"n11","text":"She wasn't looking for his mistakes.","at":97.458,"t0":48.729,"t1":50.911},{"id":"n12","text":"She was trying to prove she hadn't made one.","at":102.422,"t0":51.211,"t1":54.484},{"id":"n13","text":"And that knock wasn't the police.","at":109.568,"t0":54.784,"t1":56.966},{"id":"n14","text":"It was you.","at":114.53,"t0":57.265,"t1":58.356},{"id":"o10","text":"Tell them you are fine, or they are arrested too.","at":117.312,"t0":58.656,"t1":62.292},{"id":"m01","text":"I'm fine, beta. You eat.","at":125.186,"t0":62.593,"t1":64.411},{"id":"n15","text":"So you did.","at":129.422,"t0":64.711,"t1":65.802},{"id":"n16","text":"You'd never fall for this.","at":132.204,"t0":66.102,"t1":67.92},{"id":"n17","text":"You'd just believe her.","at":136.44,"t0":68.22,"t1":69.675},{"id":"n18","text":"Everything on this screen is fake, except the red button.","at":139.95,"t0":69.975,"t1":73.611},{"id":"n19","text":"She's a drawing.","at":147.822,"t0":73.911,"t1":75.002},{"id":"n20","text":"Your mother isn't.","at":150.604,"t0":75.302,"t1":76.393},{"id":"n21","text":"Have you told her?","at":153.386,"t0":76.693,"t1":78.148}];
